00055     public static function getMenuPostgresql()
00056     {
00057         global $bearsamppBins, $bearsamppLang, $bearsamppTools;
00058         $resultItems = $resultActions = '';
00059 
00060         $isEnabled = $bearsamppBins->getPostgresql()->isEnable();
00061 
00062         // Download
00063         $resultItems .= TplAestan::getItemLink(
00064             $bearsamppLang->getValue(Lang::DOWNLOAD_MORE),
00065             HttpClient::getWebsiteUrl('module/postgresql', '#releases'),
00066             false,
00067             TplAestan::GLYPH_BROWSER
00068         ) . PHP_EOL;
00069 
00070         // Enable
00071         $tplEnable = TplApp::getActionMulti(
00072             self::ACTION_ENABLE, array($isEnabled ? Config::DISABLED : Config::ENABLED),
00073             array($bearsamppLang->getValue(Lang::MENU_ENABLE), $isEnabled ? TplAestan::GLYPH_CHECK : ''),
00074             false, get_called_class()
00075         );
00076         $resultItems .= $tplEnable[TplApp::SECTION_CALL] . PHP_EOL;
00077         $resultActions .= $tplEnable[TplApp::SECTION_CONTENT] . PHP_EOL;
00078 
00079         if ($isEnabled) {
00080             $resultItems .= TplAestan::getItemSeparator() . PHP_EOL;
00081 
00082             // Versions
00083             $tplVersions = TplApp::getMenu($bearsamppLang->getValue(Lang::VERSIONS), self::MENU_VERSIONS, get_called_class());
00084             $resultItems .= $tplVersions[TplApp::SECTION_CALL] . PHP_EOL;
00085             $resultActions .= $tplVersions[TplApp::SECTION_CONTENT] . PHP_EOL;
00086 
00087             // Service
00088             $tplService = TplApp::getMenu($bearsamppLang->getValue(Lang::SERVICE), self::MENU_SERVICE, get_called_class());
00089             $resultItems .= $tplService[TplApp::SECTION_CALL] . PHP_EOL;
00090             $resultActions .= $tplService[TplApp::SECTION_CONTENT] . PHP_EOL;
00091 
00092             // Debug
00093             $tplDebug = TplApp::getMenu($bearsamppLang->getValue(Lang::DEBUG), self::MENU_DEBUG, get_called_class());
00094             $resultItems .= $tplDebug[TplApp::SECTION_CALL] . PHP_EOL;
00095             $resultActions .= $tplDebug[TplApp::SECTION_CONTENT];
00096 
00097             // Console
00098             $resultItems .= TplAestan::getItemPowerShell(
00099                 $bearsamppLang->getValue(Lang::CONSOLE),
00100                 TplAestan::GLYPH_POWERSHELL,
00101                 null, $bearsamppTools->getPowerShell()->getTabTitlePostgresql(), Path::getModuleSymlinkPath($bearsamppBins->getPostgresql()), null
00102             ) . PHP_EOL;
00103 
00104             // Conf
00105             $resultItems .= TplAestan::getItemNotepad(basename($bearsamppBins->getPostgresql()->getConf()), $bearsamppBins->getPostgresql()->getConf()) . PHP_EOL;
00106 
00107             // Errors log
00108             $resultItems .= TplAestan::getItemNotepad($bearsamppLang->getValue(Lang::MENU_ERROR_LOGS), $bearsamppBins->getPostgresql()->getErrorLog()) . PHP_EOL;
00109         }
00110 
00111         return $resultItems . PHP_EOL . $resultActions;
00112     }
