00121     public static function getMenuPostgresqlVersions()
00122     {
00123         global $bearsamppBins;
00124         $items = '';
00125         $actions = '';
00126 
00127         foreach ($bearsamppBins->getPostgresql()->getVersionList() as $version) {
00128             $tplSwitchPostgresqlVersion = TplApp::getActionMulti(
00129                 self::ACTION_SWITCH_VERSION, array($version),
00130                 array($version, $version == $bearsamppBins->getPostgresql()->getVersion() ? TplAestan::GLYPH_CHECK : ''),
00131                 false, get_called_class()
00132             );
00133 
00134             // Item
00135             $items .= $tplSwitchPostgresqlVersion[TplApp::SECTION_CALL] . PHP_EOL;
00136 
00137             // Action
00138             $actions .= PHP_EOL . $tplSwitchPostgresqlVersion[TplApp::SECTION_CONTENT];
00139         }
00140 
00141         return $items . $actions;
00142     }
