00184     public static function getMenuPostgresqlService()
00185     {
00186         global $bearsamppLang, $bearsamppBins;
00187 
00188         $tplChangePort = TplApp::getActionMulti(
00189             self::ACTION_CHANGE_PORT, null,
00190             array($bearsamppLang->getValue(Lang::MENU_CHANGE_PORT), TplAestan::GLYPH_NETWORK),
00191             false, get_called_class()
00192         );
00193 
00194         $isInstalled = $bearsamppBins->getPostgresql()->getService()->isInstalled();
00195 
00196         $result = TplAestan::getItemActionServiceStart($bearsamppBins->getPostgresql()->getService()->getName()) . PHP_EOL .
00197             TplAestan::getItemActionServiceStop($bearsamppBins->getPostgresql()->getService()->getName()) . PHP_EOL .
00198             TplAestan::getItemActionServiceRestart($bearsamppBins->getPostgresql()->getService()->getName()) . PHP_EOL .
00199             TplAestan::getItemSeparator() . PHP_EOL .
00200             TplApp::getActionRun(
00201                 Action::CHECK_PORT, array($bearsamppBins->getPostgresql()->getName(), $bearsamppBins->getPostgresql()->getPort()),
00202                 array(sprintf($bearsamppLang->getValue(Lang::MENU_CHECK_PORT), $bearsamppBins->getPostgresql()->getPort()), TplAestan::GLYPH_LIGHT)
00203             ) . PHP_EOL .
00204             $tplChangePort[TplApp::SECTION_CALL] . PHP_EOL;
00205 
00206         $tplChangeRootPwd = null;
00207         if ($isInstalled) {
00208             $tplChangeRootPwd = TplApp::getActionMulti(
00209                 self::ACTION_CHANGE_ROOT_PWD, null,
00210                 array($bearsamppLang->getValue(Lang::MENU_CHANGE_ROOT_PWD), TplAestan::GLYPH_PASSWORD),
00211                 !$isInstalled, get_called_class()
00212             );
00213 
00214             $result .= $tplChangeRootPwd[TplApp::SECTION_CALL] . PHP_EOL;
00215         }
00216 
00217         if (!$isInstalled) {
00218             $tplInstallService = TplApp::getActionMulti(
00219                 self::ACTION_INSTALL_SERVICE, null,
00220                 array($bearsamppLang->getValue(Lang::MENU_INSTALL_SERVICE), TplAestan::GLYPH_SERVICE_INSTALL),
00221                 $isInstalled, get_called_class()
00222             );
00223 
00224             $result .= $tplInstallService[TplApp::SECTION_CALL] . PHP_EOL . PHP_EOL .
00225             $tplInstallService[TplApp::SECTION_CONTENT] . PHP_EOL;
00226         } else {
00227             $tplRemoveService = TplApp::getActionMulti(
00228                 self::ACTION_REMOVE_SERVICE, null,
00229                 array($bearsamppLang->getValue(Lang::MENU_REMOVE_SERVICE), TplAestan::GLYPH_SERVICE_REMOVE),
00230                 !$isInstalled, get_called_class()
00231             );
00232 
00233             $result .= $tplRemoveService[TplApp::SECTION_CALL] . PHP_EOL . PHP_EOL .
00234             $tplRemoveService[TplApp::SECTION_CONTENT] . PHP_EOL;
00235         }
00236 
00237         $result .= $tplChangePort[TplApp::SECTION_CONTENT] . PHP_EOL .
00238             ($tplChangeRootPwd != null ? $tplChangeRootPwd[TplApp::SECTION_CONTENT] . PHP_EOL : '');
00239 
00240         return $result;
00241     }
